parameters.jsCode:
// The model was asked for JSON. Parse it defensively: a model that
// wraps its answer in a code fence, or answers in prose, must not turn
// a good transcription into a failed execution.
const raw = $input.first().json.choices[0].message.content || '';
const transcript = $('Whisper Transcribe').first().json.text || '';
const title = $('Recording Upload').first().json.body?.title || 'untitled';

const stripped = raw.replace(/^\s*```(?:json)?/i, '').replace(/```\s*$/, '').trim();
const start = stripped.indexOf('{');
const end = stripped.lastIndexOf('}');

let notes = null;
if (start !== -1 && end > start) {
  try {
    notes = JSON.parse(stripped.slice(start, end + 1));
  } catch (e) {
    notes = null;
  }
}

const asArray = (v) => (Array.isArray(v) ? v : []);

return [{
  json: {
    title,
    parsed: notes !== null,
    summary: notes?.summary ?? '',
    decisions: asArray(notes?.decisions),
    action_items: asArray(notes?.action_items),
    open_questions: asArray(notes?.open_questions),
    raw_reply: notes === null ? raw : undefined,
    transcript,
  },
}];
